#include <cstdint>
#include <format>
#include <memory>
#include <utility>

#include <example_interfaces/srv/trigger.hpp>
#include <rclcpp/rclcpp.hpp>
#include <std_msgs/msg/int64.hpp>

// Counts heartbeats between two calls. No ROS in here, so a unit test can drive it.
class HeartbeatTally {
 public:
  void add() { ++count_; }

  // Returns the count since the last call and starts again from zero.
  [[nodiscard]] std::int64_t take() { return std::exchange(count_, 0); }

 private:
  std::int64_t count_ = 0;
};

class TallyServer : public rclcpp::Node {
 public:
  using Trigger = example_interfaces::srv::Trigger;

  explicit TallyServer(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("tally", options) {
    subscription_ = create_subscription<std_msgs::msg::Int64>(
        "heartbeat", rclcpp::QoS(rclcpp::KeepLast(10)), [this](const std_msgs::msg::Int64&) { tally_.add(); });
    service_ = create_service<Trigger>(
        "~/take",
        [this](const std::shared_ptr<Trigger::Request>, std::shared_ptr<Trigger::Response> response) {
          response->success = true;
          response->message = std::format("{} heartbeats since the last call", tally_.take());
        });
  }

 private:
  HeartbeatTally tally_;
  rclcpp::Subscription<std_msgs::msg::Int64>::SharedPtr subscription_;
  rclcpp::Service<Trigger>::SharedPtr service_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<TallyServer>());
  rclcpp::shutdown();
}

#include <chrono>
#include <cstdint>
#include <memory>
#include <optional>

#include <example_interfaces/srv/trigger.hpp>
#include <rclcpp/rclcpp.hpp>

// Keeps one request in flight and says when to give up on it. Time comes in as an argument.
class OneRequest {
 public:
  explicit OneRequest(std::chrono::nanoseconds limit) : limit_(limit) {}

  [[nodiscard]] bool may_send() const { return !in_flight_; }

  // The id of the request in flight if it has waited longer than the limit.
  [[nodiscard]] std::optional<std::int64_t> overdue(std::chrono::nanoseconds now) const {
    if (in_flight_ && now - in_flight_->sent_at > limit_) return in_flight_->id;
    return std::nullopt;
  }

  void sent(std::int64_t id, std::chrono::nanoseconds now) { in_flight_ = InFlight{.id = id, .sent_at = now}; }
  void finished() { in_flight_.reset(); }

 private:
  struct InFlight {
    std::int64_t id;
    std::chrono::nanoseconds sent_at;
  };

  std::chrono::nanoseconds limit_;
  std::optional<InFlight> in_flight_;
};

class TallyClient : public rclcpp::Node {
 public:
  using Trigger = example_interfaces::srv::Trigger;

  explicit TallyClient(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("tally_client", options), request_(std::chrono::seconds(5)) {
    client_ = create_client<Trigger>("/tally/take");
    timer_ = create_timer(std::chrono::seconds(2), [this] { ask(); });
  }

 private:
  void ask() {
    const std::chrono::nanoseconds stamp{now().nanoseconds()};
    if (const auto stale = request_.overdue(stamp)) {
      client_->remove_pending_request(*stale);
      request_.finished();
      RCLCPP_WARN(get_logger(), "no response within 5 s, request abandoned");
    }
    if (!request_.may_send() || !client_->service_is_ready()) return;

    const auto sent = client_->async_send_request(
        std::make_shared<Trigger::Request>(), [this](rclcpp::Client<Trigger>::SharedFuture future) {
          request_.finished();
          RCLCPP_INFO(get_logger(), "%s", future.get()->message.c_str());
        });
    request_.sent(sent.request_id, stamp);
  }

  OneRequest request_;
  rclcpp::Client<Trigger>::SharedPtr client_;
  rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<TallyClient>());
  rclcpp::shutdown();
}

#include <chrono>
#include <cstdint>
#include <memory>
#include <optional>
#include <utility>
#include <vector>

#include <example_interfaces/action/fibonacci.hpp>
#include <rclcpp/rclcpp.hpp>
#include <rclcpp_action/rclcpp_action.hpp>

// F(0) to F(order), one term per step. No ROS in here, so a unit test can drive it.
class FibonacciJob {
 public:
  static constexpr std::int32_t max_order = 46;  // F(47) = 2971215073 doesn't fit in std::int32_t

  [[nodiscard]] static std::optional<FibonacciJob> start(std::int32_t order) {
    if (order < 1 || order > max_order) return std::nullopt;
    return FibonacciJob(order);
  }

  [[nodiscard]] bool done() const { return std::ssize(terms_) > order_; }
  void step() { terms_.push_back(terms_.back() + terms_[std::ssize(terms_) - 2]); }
  [[nodiscard]] const std::vector<std::int32_t>& terms() const { return terms_; }

 private:
  explicit FibonacciJob(std::int32_t order) : order_(order) {}

  std::int32_t order_;
  std::vector<std::int32_t> terms_{0, 1};
};

class FibonacciServer : public rclcpp::Node {
 public:
  using Fibonacci = example_interfaces::action::Fibonacci;
  using GoalHandle = rclcpp_action::ServerGoalHandle<Fibonacci>;

  explicit FibonacciServer(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("fibonacci_server", options) {
    server_ = rclcpp_action::create_server<Fibonacci>(
        this, "fibonacci",
        [this](const rclcpp_action::GoalUUID&, std::shared_ptr<const Fibonacci::Goal> goal) {
          return on_goal(goal->order);
        },
        [this](std::shared_ptr<GoalHandle>) {
          RCLCPP_INFO(get_logger(), "cancel requested");
          return rclcpp_action::CancelResponse::ACCEPT;
        },
        [this](std::shared_ptr<GoalHandle> handle) { on_accepted(std::move(handle)); });
  }

 private:
  struct Running {
    std::shared_ptr<GoalHandle> handle;  // the action server keeps only a weak pointer
    FibonacciJob job;
  };

  rclcpp_action::GoalResponse on_goal(std::int32_t order) {
    if (running_) {
      RCLCPP_WARN(get_logger(), "busy, rejecting order %d", order);
      return rclcpp_action::GoalResponse::REJECT;
    }
    if (!FibonacciJob::start(order)) {
      RCLCPP_WARN(get_logger(), "order %d is outside 1 to %d", order, FibonacciJob::max_order);
      return rclcpp_action::GoalResponse::REJECT;
    }
    return rclcpp_action::GoalResponse::ACCEPT_AND_EXECUTE;
  }

  void on_accepted(std::shared_ptr<GoalHandle> handle) {
    auto job = FibonacciJob::start(handle->get_goal()->order);
    if (!job) return;  // on_goal already rejected such orders
    running_ = Running{.handle = std::move(handle), .job = *std::move(job)};
    timer_ = create_timer(std::chrono::milliseconds(200), [this] { on_tick(); });
  }

  // One term per tick. Each tick returns at once, so cancel requests get through in between.
  void on_tick() {
    if (!running_) return;
    auto& [handle, job] = *running_;
    auto result = std::make_shared<Fibonacci::Result>();
    if (handle->is_canceling()) {
      result->sequence = job.terms();
      handle->canceled(result);
      RCLCPP_INFO(get_logger(), "canceled with %zu terms", job.terms().size());
      finish();
      return;
    }
    if (!job.done()) {
      job.step();
      auto feedback = std::make_shared<Fibonacci::Feedback>();
      feedback->sequence = job.terms();
      handle->publish_feedback(feedback);
    }
    if (job.done()) {
      result->sequence = job.terms();
      handle->succeed(result);
      RCLCPP_INFO(get_logger(), "succeeded with %zu terms", job.terms().size());
      finish();
    }
  }

  void finish() {
    timer_->cancel();
    running_.reset();
  }

  rclcpp_action::Server<Fibonacci>::SharedPtr server_;
  rclcpp::TimerBase::SharedPtr timer_;
  std::optional<Running> running_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<FibonacciServer>());
  rclcpp::shutdown();
}

#include <chrono>
#include <cstdint>
#include <memory>

#include <example_interfaces/action/fibonacci.hpp>
#include <rclcpp/rclcpp.hpp>
#include <rclcpp_action/rclcpp_action.hpp>

// Says when to cancel: on a fixed feedback message. No ROS in here, so a unit test can drive it.
class CancelAfter {
 public:
  explicit CancelAfter(std::int32_t feedback_count) : left_(feedback_count) {}

  // True on the feedback message that reaches the count, false before and after it.
  [[nodiscard]] bool on_feedback() { return --left_ == 0; }

 private:
  std::int32_t left_;
};

[[nodiscard]] const char* name_of(rclcpp_action::ResultCode code) {
  switch (code) {
    case rclcpp_action::ResultCode::SUCCEEDED: return "SUCCEEDED";
    case rclcpp_action::ResultCode::CANCELED: return "CANCELED";
    case rclcpp_action::ResultCode::ABORTED: return "ABORTED";
    case rclcpp_action::ResultCode::UNKNOWN: return "UNKNOWN";
  }
  return "not a result code";
}

class FibonacciClient : public rclcpp::Node {
 public:
  using Fibonacci = example_interfaces::action::Fibonacci;
  using GoalHandle = rclcpp_action::ClientGoalHandle<Fibonacci>;

  explicit FibonacciClient(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("fibonacci_client", options) {
    client_ = rclcpp_action::create_client<Fibonacci>(this, "fibonacci");
    timer_ = create_timer(std::chrono::milliseconds(500), [this] { send_when_ready(); });
  }

 private:
  void send_when_ready() {
    if (!client_->action_server_is_ready()) {
      RCLCPP_INFO(get_logger(), "waiting for the action server");
      return;
    }
    timer_->cancel();  // one goal only

    rclcpp_action::Client<Fibonacci>::SendGoalOptions options;
    options.goal_response_callback = [this](const GoalHandle::SharedPtr& handle) {
      if (!handle) {
        RCLCPP_ERROR(get_logger(), "goal rejected");
        rclcpp::shutdown();
        return;
      }
      goal_handle_ = handle;  // the action client keeps only a weak pointer
    };
    options.feedback_callback = [this](GoalHandle::SharedPtr,
                                       const std::shared_ptr<const Fibonacci::Feedback> feedback) {
      RCLCPP_INFO(get_logger(), "feedback: %d", feedback->sequence.back());
      if (cancel_after_.on_feedback()) {
        RCLCPP_INFO(get_logger(), "requesting cancel");
        client_->async_cancel_goal(goal_handle_);
      }
    };
    options.result_callback = [this](const GoalHandle::WrappedResult& result) {
      RCLCPP_INFO(get_logger(), "finished as %s with %zu terms", name_of(result.code),
                  result.result->sequence.size());
      goal_handle_.reset();
      rclcpp::shutdown();
    };

    Fibonacci::Goal goal;
    goal.order = 20;
    client_->async_send_goal(goal, options);
  }

  rclcpp_action::Client<Fibonacci>::SharedPtr client_;
  rclcpp::TimerBase::SharedPtr timer_;
  GoalHandle::SharedPtr goal_handle_;
  CancelAfter cancel_after_{5};
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<FibonacciClient>());
  rclcpp::shutdown();
}

void ask() {
  auto sent = client_->async_send_request(std::make_shared<Trigger::Request>());
  // Waits for a response that only this thread can take in.
  const auto response = sent.future.get();
  RCLCPP_INFO(get_logger(), "%s", response->message.c_str());
}

#include <chrono>
#include <deque>
#include <functional>
#include <future>
#include <iostream>
#include <utility>

// Runs queued callbacks one at a time on the calling thread, as a single-threaded executor does.
class Loop {
 public:
  void post(std::function<void()> callback) { ready_.push_back(std::move(callback)); }

  void run() {
    while (!ready_.empty()) {
      const auto callback = std::move(ready_.front());
      ready_.pop_front();
      callback();
    }
  }

 private:
  std::deque<std::function<void()>> ready_;
};

int main() {
  Loop loop;
  std::promise<int> response;
  std::future<int> future = response.get_future();

  loop.post([&] {  // the timer callback
    std::cout << "timer: request sent, waiting for the response\n";
    // The server has answered. The loop still has to run the step that takes the answer in.
    loop.post([&] {
      response.set_value(5);
      std::cout << "loop: response taken in\n";
    });
    if (future.wait_for(std::chrono::milliseconds(200)) == std::future_status::timeout) {
      std::cout << "timer: gave up after 200 ms\n";
    }
  });
  loop.run();
  std::cout << "main: the response is " << future.get() << "\n";
}
